    while ((i < m) && (j < n)) {

        int i_cir = (A_S_start + i) % tile_size;

        int j_cir = (B_S_start + j) % tile_size;

        if (A[i_cir] <= B[j_cir]) {

            C[k++] = A[i_cir]; i++;

